// Program.cs
builder.Services.AddTempoBlazor();
builder.Services.AddWireframeComponentProvider<MarketingComponentProvider>();

// MarketingComponentProvider.cs
public class MarketingComponentProvider : IWireframeComponentProvider
{
    public string ProviderId => "Marketing";
    public int Priority => 10;

    public IEnumerable<WireframeComponentDef> GetDefinitions()
    {
        yield return new WireframeComponentDef
        {
            Type        = "HeroBanner",
            Category    = "Marketing",
            DisplayName = "Hero Banner",
            Icon        = "image",
            DefaultWidth  = 800,
            DefaultHeight = 200,
            IsBuiltIn   = false,
            RenderSvg   = (el, b) =>
            {
                var sb = new StringBuilder();
                sb.Append($"<rect width='{el.W}' height='{el.H}' fill='#1e293b' rx='8'/>");
                sb.Append($"<text x='{el.W/2}' y='{el.H/2}' fill='white' text-anchor='middle' dominant-baseline='middle' font-size='18'>Hero Banner</text>");
                b.AddMarkupContent(0, sb.ToString());
            },
            Props = [
                new PropDef { Name = "headline",  DisplayName = "Headline",  Type = PropType.String },
                new PropDef { Name = "subheadline", DisplayName = "Subheadline", Type = PropType.String },
            ]
        };
    }
}
